//! Append-only JSONL event log for session persistence.
//!
//! [`LogWriter`] appends one line of JSON per event to an `events.jsonl` file.
//! Each line is a complete, independently parseable JSON object.

use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::Path;

use chrono::{DateTime, Utc};
use serde::Serialize;

/// One entry in the session event log.
#[derive(Debug, Clone, Serialize, serde::Deserialize)]
#[serde(tag = "kind")]
pub enum LogEntry {
    /// Session directory first created.
    #[serde(rename = "session_created")]
    SessionCreated {
        ts: DateTime<Utc>,
        turn: u64,
        data: SessionCreatedData,
    },
    /// Session opened (including first open after creation).
    #[serde(rename = "session_opened")]
    SessionOpened {
        ts: DateTime<Utc>,
        turn: u64,
        data: SessionOpenedData,
    },
    /// Session closed cleanly.
    #[serde(rename = "session_closed")]
    SessionClosed {
        ts: DateTime<Utc>,
        turn: u64,
        data: SessionClosedData,
    },
    /// User input at the start of a turn.
    #[serde(rename = "user_input")]
    UserInput {
        ts: DateTime<Utc>,
        turn: u64,
        data: UserInputData,
    },
    /// Prompt sent to the LLM.
    #[serde(rename = "llm_prompt")]
    LlmPrompt {
        ts: DateTime<Utc>,
        turn: u64,
        data: LlmPromptData,
    },
    /// Response received from the LLM.
    #[serde(rename = "llm_response")]
    LlmResponse {
        ts: DateTime<Utc>,
        turn: u64,
        data: LlmResponseData,
    },
    /// A tool was executed.
    #[serde(rename = "tool_execution")]
    ToolExecution {
        ts: DateTime<Utc>,
        turn: u64,
        data: ToolExecutionData,
    },
    /// A turn completed successfully.
    #[serde(rename = "turn_complete")]
    TurnComplete {
        ts: DateTime<Utc>,
        turn: u64,
        data: TurnCompleteData,
    },
    /// An error occurred during a turn.
    #[serde(rename = "error")]
    Error {
        ts: DateTime<Utc>,
        turn: u64,
        data: ErrorData,
    },
}

// --- Data structs for each variant ---

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct SessionCreatedData {
    pub session_id: String,
    pub name: String,
    pub model: String,
    pub system_prompt: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct SessionOpenedData {
    pub session_id: String,
    pub name: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct SessionClosedData {
    pub session_id: String,
    pub name: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct UserInputData {
    pub text: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct LlmPromptData {
    pub provider: String,
    pub model: String,
    pub messages: serde_json::Value,
    pub tool_definitions: serde_json::Value,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct LlmResponseData {
    pub message_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub text: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reasoning: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCallData>>,
    pub usage: UsageData,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct ToolCallData {
    pub id: String,
    pub name: String,
    pub arguments: serde_json::Value,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct UsageData {
    pub input_tokens: u32,
    pub output_tokens: u32,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct ToolExecutionData {
    pub tool_call_id: String,
    pub name: String,
    pub arguments: serde_json::Value,
    pub result: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct TurnCompleteData {
    pub text: String,
    pub tool_calls: usize,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct ErrorData {
    pub stage: ErrorStage,
    pub message: String,
}

#[derive(Debug, Clone, Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ErrorStage {
    LlmCall,
    ToolExecution,
}

// --- Helpers for constructing entries ---

impl LogEntry {
    pub fn session_created(
        ts: DateTime<Utc>,
        turn: u64,
        session_id: String,
        name: String,
        model: String,
        system_prompt: String,
    ) -> Self {
        LogEntry::SessionCreated {
            ts,
            turn,
            data: SessionCreatedData {
                session_id,
                name,
                model,
                system_prompt,
            },
        }
    }

    pub fn session_opened(ts: DateTime<Utc>, turn: u64, session_id: String, name: String) -> Self {
        LogEntry::SessionOpened {
            ts,
            turn,
            data: SessionOpenedData { session_id, name },
        }
    }

    pub fn session_closed(ts: DateTime<Utc>, turn: u64, session_id: String, name: String) -> Self {
        LogEntry::SessionClosed {
            ts,
            turn,
            data: SessionClosedData { session_id, name },
        }
    }

    pub fn user_input(ts: DateTime<Utc>, turn: u64, text: String) -> Self {
        LogEntry::UserInput {
            ts,
            turn,
            data: UserInputData { text },
        }
    }

    pub fn llm_prompt(
        ts: DateTime<Utc>,
        turn: u64,
        provider: String,
        model: String,
        messages: serde_json::Value,
        tool_definitions: serde_json::Value,
    ) -> Self {
        LogEntry::LlmPrompt {
            ts,
            turn,
            data: LlmPromptData {
                provider,
                model,
                messages,
                tool_definitions,
            },
        }
    }

    pub fn llm_response(
        ts: DateTime<Utc>,
        turn: u64,
        message_id: Option<String>,
        text: Option<String>,
        reasoning: Option<String>,
        tool_calls: Option<Vec<ToolCallData>>,
        usage: UsageData,
    ) -> Self {
        LogEntry::LlmResponse {
            ts,
            turn,
            data: LlmResponseData {
                message_id,
                text,
                reasoning,
                tool_calls,
                usage,
            },
        }
    }

    pub fn tool_execution(
        ts: DateTime<Utc>,
        turn: u64,
        tool_call_id: String,
        name: String,
        arguments: serde_json::Value,
        result: String,
    ) -> Self {
        LogEntry::ToolExecution {
            ts,
            turn,
            data: ToolExecutionData {
                tool_call_id,
                name,
                arguments,
                result,
            },
        }
    }

    pub fn turn_complete(ts: DateTime<Utc>, turn: u64, text: String, tool_calls: usize) -> Self {
        LogEntry::TurnComplete {
            ts,
            turn,
            data: TurnCompleteData { text, tool_calls },
        }
    }

    pub fn error(ts: DateTime<Utc>, turn: u64, stage: ErrorStage, message: String) -> Self {
        LogEntry::Error {
            ts,
            turn,
            data: ErrorData { stage, message },
        }
    }

    /// Timestamp of this entry.
    pub fn ts(&self) -> DateTime<Utc> {
        match self {
            LogEntry::SessionCreated { ts, .. }
            | LogEntry::SessionOpened { ts, .. }
            | LogEntry::SessionClosed { ts, .. }
            | LogEntry::UserInput { ts, .. }
            | LogEntry::LlmPrompt { ts, .. }
            | LogEntry::LlmResponse { ts, .. }
            | LogEntry::ToolExecution { ts, .. }
            | LogEntry::TurnComplete { ts, .. }
            | LogEntry::Error { ts, .. } => *ts,
        }
    }

    /// Turn number of this entry.
    pub fn turn(&self) -> u64 {
        match self {
            LogEntry::SessionCreated { turn, .. }
            | LogEntry::SessionOpened { turn, .. }
            | LogEntry::SessionClosed { turn, .. }
            | LogEntry::UserInput { turn, .. }
            | LogEntry::LlmPrompt { turn, .. }
            | LogEntry::LlmResponse { turn, .. }
            | LogEntry::ToolExecution { turn, .. }
            | LogEntry::TurnComplete { turn, .. }
            | LogEntry::Error { turn, .. } => *turn,
        }
    }
}

// --- LogWriter ---

/// Append-only JSONL writer for session event logs.
///
/// Flushes after every write so events are durable on disk immediately.
#[derive(Debug)]
pub struct LogWriter {
    inner: BufWriter<File>,
}

impl LogWriter {
    /// Open (or create) the log file at `path` for appending.
    pub fn open(path: &Path) -> std::io::Result<Self> {
        let file = OpenOptions::new().create(true).append(true).open(path)?;
        Ok(Self {
            inner: BufWriter::new(file),
        })
    }

    /// Append one entry as a JSON line.
    pub fn write_entry(&mut self, entry: &LogEntry) -> std::io::Result<()> {
        let line = serde_json::to_string(entry)?;
        writeln!(self.inner, "{line}")?;
        self.inner.flush()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn log_path() -> PathBuf {
        std::env::temp_dir().join(format!("hanihi-log-test-{}.jsonl", uuid::Uuid::new_v4()))
    }

    #[test]
    fn write_and_read_back() {
        let path = log_path();
        let mut writer = LogWriter::open(&path).expect("open");
        let entry = LogEntry::session_created(
            Utc::now(),
            0,
            "abc".into(),
            "test".into(),
            "deepseek-chat".into(),
            "you are helpful".into(),
        );
        writer.write_entry(&entry).expect("write");

        let contents = std::fs::read_to_string(&path).expect("read");
        let parsed: LogEntry = serde_json::from_str(contents.trim()).expect("parse");
        match &parsed {
            LogEntry::SessionCreated { data, .. } => {
                assert_eq!(data.name, "test");
                assert_eq!(data.model, "deepseek-chat");
            }
            _ => panic!("expected SessionCreated"),
        }

        std::fs::remove_file(&path).unwrap_or(());
    }

    #[test]
    fn multiple_entries_are_lines() {
        let path = log_path();
        let mut writer = LogWriter::open(&path).expect("open");
        let now = Utc::now();
        writer
            .write_entry(&LogEntry::user_input(now, 1, "hello".into()))
            .expect("write");
        writer
            .write_entry(&LogEntry::turn_complete(now, 1, "hi".into(), 0))
            .expect("write");

        let contents = std::fs::read_to_string(&path).expect("read");
        let lines: Vec<&str> = contents.lines().collect();
        assert_eq!(lines.len(), 2);

        std::fs::remove_file(&path).unwrap_or(());
    }
}

data.result:
//! # hanihi-cli
//!
//! REPL front-end for the agent harness: reedline line editor on top of
//! [`hanihi_core::Agent`]. Supports sessions (`--session` / `--new-session`),
//! one-shot turns (`--once`), and MCP stdio servers.

use std::path::PathBuf;
use std::sync::Arc;

use clap::Parser;
use hanihi_core::agent::Agent;
use hanihi_core::error::AgentError;
use hanihi_core::session::SessionManager;
use hanihi_core::{
    McpClient, SourceTree, builtin_echo, builtin_get_time, builtin_list_dir, builtin_read_file,
    connect_chat_model,
};
use reedline::{DefaultPrompt, Reedline, Signal};
use rig::completion::CompletionModel;
use tracing_subscriber::EnvFilter;

const DEFAULT_WORKING_DIR: &str = "./working";

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
        long,
        env = "LLM_BASE_URL",
        default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/mcp-echo-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
        .trim_start_matches("https://")
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
        .trim_start_matches("api-")
        .split('.')
        .next()
        .unwrap_or("unknown")
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let api_key = args
        .api_key
        .filter(|k| !k.is_empty())
        .ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
        args.working_dir
    } else {
        std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
        (name.clone(), true)
    } else {
        let name = args.session.clone();
        // Auto-create default-session if it doesn't exist.
        let is_new = name == "default-session" && !mgr.exists(&name);
        (name, is_new)
    };

    // Create or open the session.
    if is_new {
        if session_name == "default-session" {
            mgr.create_default(&args.model, hanihi_core::agent::DEFAULT_SYSTEM_PROMPT)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("auto-created session 'default-session'");
        } else {
            mgr.create(
                &session_name,
                &args.model,
                hanihi_core::agent::DEFAULT_SYSTEM_PROMPT,
            )
            .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("created session '{session_name}'");
        }
    } else {
        mgr.open(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
    }

    // Build the agent.
    let mut agent = connect_chat_model(&args.base_url, &api_key, &args.model)?;
    agent.add_tool(builtin_get_time());
    agent.add_tool(builtin_echo());

    // Source-tree tools: read/list the enclosing git repository. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see.
    match SourceTree::open() {
        Ok(tree) => {
            let tree = Arc::new(tree);
            agent.add_tool(builtin_read_file(tree.clone()));
            agent.add_tool(builtin_list_dir(tree));
        }
        Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
        let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
        let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
            name: "<mcp>".into(),
            message: "empty --mcp-command".into(),
        })?;
        let client = McpClient::connect_stdio(program, rest).await?;
        let tools = client.tool_defs().await?;
        let count = tools.len();
        for tool in tools {
            agent.add_tool(tool);
        }
        println!("attached MCP server '{program}': {count} tool(s)");
    }

    println!(
        "agent ready: model={} tools={} session='{session_name}'",
        args.model,
        agent.tool_count(),
    );

    // Get a mutable reference to the open session.
    let session = mgr
        .open(&session_name)
        .map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    if let Some(prompt) = args.once {
        let summary = session
            .run(&mut agent, provider, &args.model, &prompt)
            .await?;
        println!("{}", summary.text);
        println!(
            "[tool calls: {} | tokens: {} in / {} out]",
            summary.tool_calls, summary.usage.input_tokens, summary.usage.output_tokens
        );
        mgr.close(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        return Ok(());
    }

    repl(session, agent, provider, &args.model).await?;

    mgr.close(&session_name)
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Interactive readline loop.
async fn repl<M: CompletionModel>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
) -> Result<(), AgentError> {
    let mut editor = Reedline::create();
    let prompt = DefaultPrompt::default();

    loop {
        match editor.read_line(&prompt) {
            Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
                let line = line.trim().to_string();
                match line.as_str() {
                    "" => continue,
                    "/quit" | "/exit" => break,
                    "/help" => {
                        println!(
                            "commands: /help /tools /clear /session /quit — anything else is sent to the model"
                        );
                        continue;
                    }
                    "/tools" => {
                        for def in agent.tool_definitions() {
                            println!("- {}: {}", def.name, def.description);
                        }
                        continue;
                    }
                    "/clear" => {
                        agent.clear_history();
                        println!("history cleared");
                        continue;
                    }
                    "/session" => {
                        println!(
                            "session: '{}' (id={}) turn={}",
                            session.name, session.id, session.turn
                        );
                        continue;
                    }
                    _ => {}
                }
                match session.run(&mut agent, provider, model_name, &line).await {
                    Ok(summary) => {
                        println!("{}", summary.text);
                        println!(
                            "[tool calls: {} | tokens: {} in / {} out]",
                            summary.tool_calls,
                            summary.usage.input_tokens,
                            summary.usage.output_tokens
                        );
                    }
                    Err(e) => eprintln!("error: {e}"),
                }
            }
            Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
            Ok(Signal::CtrlD) => break,
            Ok(_) => continue,
            Err(e) => {
                eprintln!("readline error: {e}");
                break;
            }
        }
    }

    // Clean shutdown — session closed by caller.
    Ok(())
}

//! Mandatory filesystem lock for session directories.
//!
//! Uses `fs2::FileExt` for cross-platform file locking. The lock is
//! exclusive and held for the lifetime of the `SessionGuard`.

use std::fs::{File, OpenOptions};
use std::io;
use std::path::{Path, PathBuf};

use fs2::FileExt;

/// Holds an exclusive lock on a session directory's `.lock` file.
///
/// The lock is released when the guard is dropped.
#[derive(Debug)]
pub struct SessionGuard {
    _file: File,
    _path: PathBuf,
}

impl SessionGuard {
    /// Acquire an exclusive lock on `<dir>/.lock`.
    ///
    /// Fails immediately if another process holds the lock.
    pub fn acquire(dir: &Path) -> io::Result<Self> {
        let lock_path = dir.join(".lock");
        let file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .read(true)
            .write(true)
            .open(&lock_path)?;
        file.try_lock_exclusive()?;
        Ok(Self {
            _file: file,
            _path: lock_path,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn tmp_dir() -> PathBuf {
        let dir = std::env::temp_dir().join(format!("hanihi-lock-test-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn acquire_and_drop() {
        let dir = tmp_dir();
        let guard = SessionGuard::acquire(&dir).expect("acquire");
        let lock_path = dir.join(".lock");
        assert!(lock_path.exists());
        drop(guard);
        // After drop the lock file still exists on disk (we don't delete it),
        // but the lock should be released so a second acquire succeeds.
        let _guard2 = SessionGuard::acquire(&dir).expect("second acquire after drop");
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn exclusive_lock_fails() {
        let dir = tmp_dir();
        let _guard = SessionGuard::acquire(&dir).expect("first acquire");
        let result = SessionGuard::acquire(&dir);
        assert!(result.is_err());
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }
}

